def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def is_power_of_two(n):
    # Checks if n > 0 and only one bit is set
    return n > 0 and (n & (n - 1) == 0)

count = 0
checked_numbers = set()

for m in range(2, 2001):
    if m in checked_numbers:
        continue

    is_p = is_prime(m)
    is_2k = is_power_of_two(m)

    if is_p or is_2k:
        count += 1
        checked_numbers.add(m)

print(f"The total count of primes and powers of two between 2 and 2000 is: {count}")
